WITH with_gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM payments), sessions_payments AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN is_new_burst >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_burst_tier, DATE_TRUNC('YEAR', paid_at) AS year_start, MAX(island_id) FILTER (WHERE status = 'SUCCESS') AS success_max_island_id, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, MAX(is_new_burst) FILTER (WHERE method = 'cash') AS cash_max_is_new_burst, COUNT(DISTINCT status) AS distinct_status, SUM(CASE WHEN status = 'FAILED' THEN amount ELSE 0 END) AS failed_amount, GROUPING_ID() AS grouping_id FROM sessions_payments GROUP BY ROLLUP (CASE WHEN is_new_burst >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('YEAR', paid_at))
